export type MessageKey = keyof typeof MESSAGES;
export type TranslationValues = Record<string, string | number>;
const indexes = { en: 0, de: 1, fr: 2, ru: 3 } as const;

export function isLanguage(value: unknown): value is Language {
  return typeof value === 'string' && (LANGUAGES as readonly string[]).includes(value);
}

export function resolveLanguage(value: unknown): Language { return isLanguage(value) ? value : 'pl'; }

export function translate(language: Language, key: MessageKey, values: TranslationValues = {}): string {
  const template = language === 'pl' ? key : MESSAGES[key][indexes[language]];
  return template.replace(/\{(\w+)\}/g, (placeholder, name: string) => {
    const value = values[name];
    return value === undefined ? placeholder : typeof value === 'number' ? new Intl.NumberFormat(LOCALES[language]).format(value) : value;
  });
}

/** Localize only our diagnostics, never arbitrary conversation text or upstream errors. */
export function localizeMessage(language: Language, message: string): string {
  if (Object.hasOwn(MESSAGES, message)) return translate(language, message as MessageKey);
  const scoped = /^([a-zA-Z0-9_.-]+): ([\s\S]+)$/.exec(message);
  if (scoped) return `${scoped[1]}: ${localizeMessage(language, scoped[2])}`;
  const directory = /^Nie można odczytać katalogu ([\s\S]+)\.$/.exec(message);
  if (directory) return translate(language, 'Nie można odczytać katalogu {path}.', { path: directory[1] });
  const file = /^Nie można odczytać ([\s\S]+)\.$/.exec(message);
  if (file) return translate(language, 'Nie można odczytać {file}.', { file: file[1] });
  return message;
}

type Unit = 'sessions' | 'agents' | 'nodes' | 'measurements';
const UNIT_FORMS: Record<Language, Record<Unit, { one: string; other: string; few?: string; many?: string }>> = {
  pl: { sessions: { one: 'sesja', few: 'sesje', other: 'sesji' }, agents: { one: 'agent', few: 'agenci', other: 'agentów' }, nodes: { one: 'węzeł', few: 'węzły', other: 'węzłów' }, measurements: { one: 'pomiar', few: 'pomiary', other: 'pomiarów' } },
  en: { sessions: { one: 'session', other: 'sessions' }, agents: { one: 'agent', other: 'agents' }, nodes: { one: 'node', other: 'nodes' }, measurements: { one: 'measurement', other: 'measurements' } },
  de: { sessions: { one: 'Sitzung', other: 'Sitzungen' }, agents: { one: 'Agent', other: 'Agenten' }, nodes: { one: 'Knoten', other: 'Knoten' }, measurements: { one: 'Messung', other: 'Messungen' } },
  fr: { sessions: { one: 'session', other: 'sessions' }, agents: { one: 'agent', other: 'agents' }, nodes: { one: 'nœud', other: 'nœuds' }, measurements: { one: 'mesure', other: 'mesures' } },
  ru: { sessions: { one: 'сессия', few: 'сессии', other: 'сессий' }, agents: { one: 'агент', few: 'агента', other: 'агентов' }, nodes: { one: 'узел', few: 'узла', other: 'узлов' }, measurements: { one: 'измерение', few: 'измерения', other: 'измерений' } },
};

export function pluralUnit(language: Language, unit: Unit, count: number): string {
  const forms = UNIT_FORMS[language][unit];
  const category = new Intl.PluralRules(LOCALES[language]).select(count);
  return forms[category as keyof typeof forms] ?? forms.other;
}
